import { test, expect } from '@playwright/test';
import { LoginPage } from './pages/LoginPage';
import { ProductsPage } from './pages/ProductsPage';
import { CartPage } from './pages/CartPage';
import { CheckoutPage } from './pages/CheckoutPage';

test.describe('E-Commerce E2E Flow', () => {
  test.beforeEach(async ({ page }) => {
    const loginPage = new LoginPage(page);
    await loginPage.navigate();
    await loginPage.login('testuser@shop.com', 'Password123');
  });

  test('TC001 - Search and filter products', async ({ page }) => {
    const products = new ProductsPage(page);
    await products.search('wireless headphones');
    await products.applyFilter('Brand', 'Sony');
    await products.sortBy('Price: Low to High');
    const count = await products.getResultCount();
    expect(count).toBeGreaterThan(0);
    const firstProduct = await products.getFirstProductName();
    expect(firstProduct).toContain('Sony');
  });

  test('TC002 - Add items to cart and update quantity', async ({ page }) => {
    const products = new ProductsPage(page);
    await products.search('laptop');
    await products.addToCart(0);
    const cart = new CartPage(page);
    await cart.navigate();
    await cart.updateQuantity(0, 2);
    const itemCount = await cart.getItemCount();
    expect(itemCount).toBe(1);
    const subtotal = await cart.getSubtotal();
    expect(subtotal).toBeGreaterThan(0);
  });

  test('TC003 - Complete checkout with payment', async ({ page }) => {
    const products = new ProductsPage(page);
    await products.addToCart(0);
    const cart = new CartPage(page);
    await cart.navigate();
    await cart.proceedToCheckout();
    const checkout = new CheckoutPage(page);
    await checkout.fillShipping({
      address: '123 Main St',
      city: 'San Francisco',
      zip: '94105',
      country: 'US'
    });
    await checkout.selectPayment('Credit Card');
    await checkout.fillCardDetails('4111111111111111', '12/28', '123');
    await checkout.placeOrder();
    await expect(checkout.orderConfirmation).toBeVisible();
    await expect(checkout.orderConfirmation).toContainText('Thank you');
  });

  test('TC004 - Validate empty cart behaviour', async ({ page }) => {
    const cart = new CartPage(page);
    await cart.navigate();
    await expect(cart.emptyCartMessage).toBeVisible();
    await expect(cart.emptyCartMessage).toContainText('empty');
    await expect(cart.checkoutButton).toBeDisabled();
  });

  test('TC005 - Remove item from cart', async ({ page }) => {
    const products = new ProductsPage(page);
    await products.addToCart(0);
    await products.addToCart(1);
    const cart = new CartPage(page);
    await cart.navigate();
    await cart.removeItem(0);
    const count = await cart.getItemCount();
    expect(count).toBe(1);
  });
});

import { test, expect } from '@playwright/test';
import { LoginPage } from './pages/LoginPage';
import { DashboardPage } from './pages/DashboardPage';
import { TransferPage } from './pages/TransferPage';
import { BillPayPage } from './pages/BillPayPage';

const TEST_USER = {
  username: 'john.doe',
  password: 'SecureBank@123',
  accountNumber: '9876543210'
};

test.describe('Banking Application - Critical Flows', () => {
  test.beforeEach(async ({ page }) => {
    const login = new LoginPage(page);
    await login.navigate();
    await login.login(TEST_USER.username, TEST_USER.password);
    await login.handleOTP('123456');
  });

  test('TC001 - Verify account summary after login', async ({ page }) => {
    const dashboard = new DashboardPage(page);
    await expect(dashboard.welcomeMessage).toContainText('Welcome');
    const balance = await dashboard.getAccountBalance('Savings');
    expect(balance).toBeGreaterThan(0);
    const accounts = await dashboard.getAccountList();
    expect(accounts.length).toBeGreaterThanOrEqual(1);
    await expect(dashboard.lastLoginTime).toBeVisible();
  });

  test('TC002 - Fund transfer between accounts', async ({ page }) => {
    const transfer = new TransferPage(page);
    await transfer.navigate();
    await transfer.selectFromAccount('Savings - 9876');
    await transfer.selectToAccount('Checking - 5432');
    await transfer.enterAmount('500.00');
    await transfer.addNote('Monthly transfer');
    await transfer.reviewTransfer();
    await expect(transfer.reviewAmount).toContainText('$500.00');
    await transfer.confirmTransfer();
    await expect(transfer.successMessage).toContainText('Transfer successful');
    await expect(transfer.transactionRef).toBeVisible();
  });

  test('TC003 - Transfer exceeds available balance', async ({ page }) => {
    const dashboard = new DashboardPage(page);
    const balance = await dashboard.getAccountBalance('Savings');
    const transfer = new TransferPage(page);
    await transfer.navigate();
    await transfer.selectFromAccount('Savings - 9876');
    await transfer.enterAmount(String(Number(balance) + 1000));
    await transfer.submitTransfer();
    await expect(transfer.errorMessage).toContainText('Insufficient funds');
    await expect(transfer.confirmButton).toBeDisabled();
  });

  test('TC004 - Pay bill to registered payee', async ({ page }) => {
    const billPay = new BillPayPage(page);
    await billPay.navigate();
    await billPay.selectPayee('Electric Company');
    await billPay.enterAmount('150.00');
    await billPay.selectPaymentDate('2026-08-01');
    await billPay.schedulePayment();
    await expect(billPay.successMessage).toContainText('Payment scheduled');
    const scheduled = await billPay.getScheduledPayments();
    expect(scheduled).toContainEqual(expect.objectContaining({ payee: 'Electric Company', amount: '$150.00' }));
  });

  test('TC005 - Transaction history filters', async ({ page }) => {
    const dashboard = new DashboardPage(page);
    await dashboard.navigateToTransactions();
    await dashboard.filterByDateRange('2026-07-01', '2026-07-25');
    await dashboard.filterByType('Transfer');
    const transactions = await dashboard.getTransactionList();
    transactions.forEach(tx => { expect(tx.type).toBe('Transfer'); });
    await dashboard.exportTransactions('CSV');
    const download = await page.waitForEvent('download');
    expect(download.suggestedFilename()).toContain('.csv');
  });
});

import { test, expect } from '@playwright/test';
import { LoginPage } from './pages/LoginPage';
import { PatientPortal } from './pages/PatientPortal';
import { AppointmentsPage } from './pages/AppointmentsPage';
import { MedicalRecordsPage } from './pages/MedicalRecordsPage';

const PATIENT = { email: 'patient@hospital.com', password: 'HealthCare@2026', mrn: 'MRN-2024-88991' };

test.describe('Healthcare Portal - Patient Flows', () => {
  test.beforeEach(async ({ page }) => {
    const login = new LoginPage(page);
    await login.navigate();
    await login.login(PATIENT.email, PATIENT.password);
    await login.acceptHIPAACompliance();
  });

  test('TC001 - Register new patient', async ({ page }) => {
    const portal = new PatientPortal(page);
    await portal.navigateToRegistration();
    await portal.fillPersonalInfo({ firstName: 'Sarah', lastName: 'Connor', dob: '1990-05-15', gender: 'Female', ssn: '123-45-6789' });
    await portal.fillContactInfo({ phone: '555-0123', email: 'sarah.connor@email.com', address: '456 Health Blvd, Medical City, MC 90210' });
    await portal.fillInsuranceInfo({ provider: 'BlueCross', policyNumber: 'BCBS-99887766', groupNumber: 'GRP-4455' });
    await portal.submitRegistration();
    await expect(portal.confirmationMessage).toContainText('Registration submitted');
    expect(await portal.getMRN()).toMatch(/^MRN-/);
  });

  test('TC002 - Schedule a new appointment', async ({ page }) => {
    const appointments = new AppointmentsPage(page);
    await appointments.navigate();
    await appointments.clickNewAppointment();
    await appointments.selectSpecialty('Cardiology');
    await appointments.selectProvider('Dr. Sarah Heart');
    await appointments.selectDate('2026-08-15');
    await appointments.selectTimeSlot('10:00 AM');
    await appointments.selectVisitType('In-Person');
    await appointments.addReason('Annual cardiac checkup');
    await appointments.confirmBooking();
    await expect(appointments.bookingConfirmation).toBeVisible();
    await expect(appointments.bookingConfirmation).toContainText('August 15, 2026');
    const upcoming = await appointments.getUpcomingAppointments();
    expect(upcoming.length).toBeGreaterThan(0);
  });

  test('TC003 - Cancel appointment within policy', async ({ page }) => {
    const appointments = new AppointmentsPage(page);
    await appointments.navigate();
    const existing = await appointments.getUpcomingAppointments();
    if (existing.length > 0) {
      await appointments.cancelAppointment(existing[0].id);
      await appointments.confirmCancellation('Schedule conflict');
      await expect(appointments.cancelSuccessMessage).toContainText('Cancelled');
    }
  });

  test('TC004 - Access and download medical records', async ({ page }) => {
    const records = new MedicalRecordsPage(page);
    await records.navigate();
    const categories = await records.getRecordCategories();
    expect(categories).toContain('Lab Results');
    expect(categories).toContain('Prescriptions');
    expect(categories).toContain('Visit Summaries');
    await records.selectCategory('Lab Results');
    const labReports = await records.getDocumentsList();
    expect(labReports.length).toBeGreaterThan(0);
    await records.downloadDocument(labReports[0].id);
    const download = await page.waitForEvent('download');
    expect(download.suggestedFilename()).toMatch(/.pdf$/);
  });

  test('TC005 - Request prescription refill', async ({ page }) => {
    const records = new MedicalRecordsPage(page);
    await records.navigate();
    await records.selectCategory('Prescriptions');
    const prescriptions = await records.getPrescriptionsList();
    const active = prescriptions.filter(p => p.status === 'Active');
    if (active.length > 0) {
      await records.requestRefill(active[0].id);
      await records.selectPharmacy('CVS Pharmacy - Main St');
      await records.confirmRefill();
      await expect(records.refillConfirmation).toContainText('Refill requested');
    }
  });
});

import { test, expect } from '@playwright/test';
import { LeadsPage } from './pages/LeadsPage';
import { ContactsPage } from './pages/ContactsPage';
import { DealsPage } from './pages/DealsPage';
import { DashboardPage } from './pages/DashboardPage';

test.describe('CRM - Sales Pipeline Automation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.fill('[data-testid="email"]', 'sales@company.com');
    await page.fill('[data-testid="password"]', 'CrmSales@2026');
    await page.click('[data-testid="login-btn"]');
    await expect(page).toHaveURL(/.*dashboard/);
  });

  test('TC001 - Create lead from web form inquiry', async ({ page }) => {
    const leads = new LeadsPage(page);
    await leads.navigate();
    await leads.clickCreateLead();
    await leads.fillLeadForm({ firstName: 'Michael', lastName: 'Johnson', company: 'TechCorp Inc.', email: 'michael@techcorp.com', phone: '555-9876', source: 'Website', status: 'New', dealValue: '50000' });
    await leads.saveLead();
    await expect(leads.successToast).toContainText('Lead created');
    const leadId = await leads.getLeadId();
    await leads.searchLead('Michael Johnson');
    await expect(leads.leadRow(leadId)).toBeVisible();
  });

  test('TC002 - Convert lead to contact and deal', async ({ page }) => {
    const leads = new LeadsPage(page);
    await leads.navigate();
    await leads.searchLead('Michael Johnson');
    await leads.clickConvert('Michael Johnson');
    await leads.selectConvertOption('Create Contact and Deal');
    await leads.fillDealInfo({ dealName: 'TechCorp Enterprise License', stage: 'Qualification', amount: '50000', closeDate: '2026-09-30', pipeline: 'Enterprise Sales' });
    await leads.confirmConversion();
    const contacts = new ContactsPage(page);
    await contacts.navigate();
    await contacts.searchContact('Michael Johnson');
    await expect(contacts.contactCard).toBeVisible();
    const deals = new DealsPage(page);
    await deals.navigate();
    await expect(deals.dealCard('TechCorp Enterprise License')).toBeVisible();
  });

  test('TC003 - Move deal through pipeline stages', async ({ page }) => {
    const deals = new DealsPage(page);
    await deals.navigate();
    await deals.searchDeal('TechCorp Enterprise License');
    await deals.openDeal('TechCorp Enterprise License');
    const stages = ['Qualification', 'Proposal', 'Negotiation', 'Closed Won'];
    for (const stage of stages) {
      await deals.moveToStage(stage);
      await deals.addStageNote('Moved to ' + stage + ' - client progressing');
      await deals.confirmStageChange();
      await expect(deals.currentStageBadge).toContainText(stage);
    }
    await expect(deals.dealStatus).toContainText('Closed Won');
  });

  test('TC004 - Add activity and notes to contact', async ({ page }) => {
    const contacts = new ContactsPage(page);
    await contacts.navigate();
    await contacts.searchContact('Michael Johnson');
    await contacts.openContact('Michael Johnson');
    await contacts.logActivity({ type: 'Call', subject: 'Discussed enterprise requirements', outcome: 'Positive - Follow up scheduled', duration: '45 min', nextSteps: 'Send proposal by Friday' });
    await contacts.saveActivity();
    const activities = await contacts.getActivities();
    expect(activities[0]).toMatchObject({ type: 'Call', subject: 'Discussed enterprise requirements' });
  });

  test('TC005 - Generate pipeline report', async ({ page }) => {
    const dashboard = new DashboardPage(page);
    await dashboard.navigate();
    const totalPipeline = await dashboard.getTotalPipelineValue();
    expect(totalPipeline).toBeGreaterThan(0);
    await dashboard.selectReportType('Pipeline by Stage');
    await dashboard.generateReport();
    await expect(dashboard.reportChart).toBeVisible();
    await dashboard.exportReport('PDF');
    const download = await page.waitForEvent('download');
    expect(download.suggestedFilename()).toContain('pipeline_report');
  });
});

import { test, expect } from '@playwright/test';
import { FlightSearchPage } from './pages/FlightSearchPage';
import { HotelSearchPage } from './pages/HotelSearchPage';
import { BookingPage } from './pages/BookingPage';
import { ItineraryPage } from './pages/ItineraryPage';

test.describe('Travel Booking Platform', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.fill('#email', 'traveler@world.com');
    await page.fill('#password', 'TravelNow@2026');
    await page.click('button:has-text("Sign In")');
    await expect(page).toHaveURL(/.*home/);
  });

  test('TC001 - Search flights with filters and sort', async ({ page }) => {
    const flights = new FlightSearchPage(page);
    await flights.navigate();
    await flights.selectTripType('Round Trip');
    await flights.setOrigin('New York (JFK)');
    await flights.setDestination('London (LHR)');
    await flights.setDates('2026-09-10', '2026-09-20');
    await flights.setPassengers({ adults: 2, children: 1 });
    await flights.search();
    await expect(flights.resultsList).toBeVisible();
    await flights.applyFilter('Stops', 'Direct only');
    await flights.applyFilter('Airline', 'British Airways');
    await flights.sortBy('Price');
    const prices = await flights.getDisplayedPrices();
    for (let i = 1; i < prices.length; i++) {
      expect(prices[i]).toBeGreaterThanOrEqual(prices[i-1]);
    }
  });

  test('TC002 - Book flight and add extras', async ({ page }) => {
    const flights = new FlightSearchPage(page);
    await flights.navigate();
    await flights.setOrigin('New York (JFK)');
    await flights.setDestination('London (LHR)');
    await flights.setDates('2026-09-10', '2026-09-20');
    await flights.search();
    await flights.selectFlight(0);
    const booking = new BookingPage(page);
    await booking.fillPassengerDetails([
      { title: 'Mr', firstName: 'James', lastName: 'Wilson', dob: '1985-03-22' },
      { title: 'Mrs', firstName: 'Emma', lastName: 'Wilson', dob: '1987-07-14' }
    ]);
    await booking.addExtraBaggage(0, '23kg');
    await booking.selectSeats(['12A', '12B']);
    await booking.selectMeal(0, 'Vegetarian');
    await booking.reviewBooking();
    const summary = await booking.getBookingSummary();
    expect(summary.totalAmount).toBeGreaterThan(0);
    await booking.confirmAndPay();
    await expect(booking.confirmationPage).toContainText('Booking confirmed');
    await expect(booking.bookingReference).toBeVisible();
  });

  test('TC003 - Search and book hotel near destination', async ({ page }) => {
    const hotels = new HotelSearchPage(page);
    await hotels.navigate();
    await hotels.setDestination('London');
    await hotels.setDates('2026-09-10', '2026-09-20');
    await hotels.setGuests(2);
    await hotels.search();
    await hotels.applyFilter('Star Rating', '4 & 5 Star');
    await hotels.applyFilter('Guest Rating', '8+');
    await hotels.sortBy('Guest Rating');
    await hotels.selectHotel(0);
    await hotels.selectRoomType('Deluxe King');
    await hotels.addToCart();
    const booking = new BookingPage(page);
    await booking.reviewCart();
    await booking.confirmAndPay();
    await expect(booking.confirmationPage).toContainText('Booking confirmed');
  });

  test('TC004 - View and modify itinerary', async ({ page }) => {
    const itinerary = new ItineraryPage(page);
    await itinerary.navigate();
    const bookings = await itinerary.getBookings();
    expect(bookings.length).toBeGreaterThan(0);
    await itinerary.expandBooking(bookings[0].id);
    await expect(itinerary.flightDetails).toBeVisible();
    await itinerary.modifyBooking(bookings[0].id);
    await itinerary.changeSeat('14C');
    await itinerary.confirmModification();
    await expect(itinerary.modificationSuccess).toContainText('Updated');
  });

  test('TC005 - Online check-in flow', async ({ page }) => {
    const itinerary = new ItineraryPage(page);
    await itinerary.navigate();
    const bookings = await itinerary.getBookings();
    const upcoming = bookings.find(b => b.status === 'Confirmed');
    if (upcoming) {
      await itinerary.clickCheckIn(upcoming.id);
      await itinerary.selectPassengerForCheckIn(0);
      await itinerary.enterPassportDetails('US', 'P12345678', '2028-12-31');
      await itinerary.acceptDangerousGoodsDeclaration();
      await itinerary.completeCheckIn();
      await expect(itinerary.boardingPass).toBeVisible();
      await itinerary.downloadBoardingPass();
      const download = await page.waitForEvent('download');
      expect(download.suggestedFilename()).toMatch(/boarding/);
    }
  });
});

import { test, expect } from '@playwright/test';
import { CoursesPage } from './pages/CoursesPage';
import { CoursePlayerPage } from './pages/CoursePlayerPage';
import { QuizPage } from './pages/QuizPage';
import { GradesPage } from './pages/GradesPage';
import { CertificatePage } from './pages/CertificatePage';

const STUDENT = { email: 'student@edulearn.com', password: 'LearnNow@2026' };

test.describe('E-Learning Platform - Student Journey', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.fill('[name="email"]', STUDENT.email);
    await page.fill('[name="password"]', STUDENT.password);
    await page.click('button[type="submit"]');
    await expect(page).toHaveURL(/.*dashboard/);
  });

  test('TC001 - Browse catalog and enroll in course', async ({ page }) => {
    const courses = new CoursesPage(page);
    await courses.navigate();
    await courses.searchCourse('Automation Testing');
    await courses.filterByCategory('Software Testing');
    await courses.filterByLevel('Intermediate');
    const results = await courses.getCourseCards();
    expect(results.length).toBeGreaterThan(0);
    await courses.clickCourse('Automation Testing Masterclass');
    await expect(courses.courseDetailTitle).toContainText('Automation Testing');
    await expect(courses.coursePrice).toBeVisible();
    await courses.clickEnroll();
    await courses.selectPaymentMethod('Card');
    await courses.completePayment();
    await expect(courses.enrollmentSuccess).toContainText('Enrolled');
    await expect(courses.startLearningButton).toBeVisible();
  });

  test('TC002 - Complete course modules and track progress', async ({ page }) => {
    const player = new CoursePlayerPage(page);
    await player.navigateToMyCourse('Automation Testing Masterclass');
    const modules = await player.getModuleList();
    expect(modules.length).toBeGreaterThan(0);
    for (const module of modules.slice(0, 3)) {
      await player.openModule(module.title);
      const lessons = await player.getLessonList();
      for (const lesson of lessons) {
        await player.playLesson(lesson.title);
        await player.waitForCompletion();
        await player.markAsComplete();
      }
    }
    const progress = await player.getCourseProgress();
    expect(progress).toBeGreaterThan(0);
    expect(progress).toBeLessThanOrEqual(100);
  });

  test('TC003 - Take quiz and verify score', async ({ page }) => {
    const quiz = new QuizPage(page);
    await quiz.navigateToQuiz('Automation Testing Masterclass', 'Module 1 Assessment');
    await quiz.startQuiz();
    const questions = await quiz.getQuestionCount();
    const answers = [{ question: 1, answer: 'B' }, { question: 2, answer: 'A' }, { question: 3, answer: 'C' }, { question: 4, answer: 'A' }, { question: 5, answer: 'B' }];
    for (const a of answers.slice(0, questions)) {
      await quiz.selectAnswer(a.question, a.answer);
    }
    await quiz.submitQuiz();
    await quiz.confirmSubmission();
    const score = await quiz.getScore();
    expect(score).toBeGreaterThanOrEqual(60);
    await expect(quiz.passFailIndicator).toBeVisible();
  });

  test('TC004 - Retake failed quiz', async ({ page }) => {
    const quiz = new QuizPage(page);
    const grades = new GradesPage(page);
    await grades.navigateToCourse('Automation Testing Masterclass');
    const quizScores = await grades.getQuizScores();
    const failed = quizScores.find(q => q.score < 60);
    if (failed) {
      await quiz.navigateToQuiz('Automation Testing Masterclass', failed.title);
      await quiz.startRetake();
      for (let i = 1; i <= (await quiz.getQuestionCount()); i++) {
        await quiz.selectAnswer(i, 'A');
      }
      await quiz.submitQuiz();
      const newScore = await quiz.getScore();
      await expect(quiz.retakeScore).toContainText(String(newScore));
    }
  });

  test('TC005 - View grades and download certificate', async ({ page }) => {
    const grades = new GradesPage(page);
    await grades.navigate();
    await grades.selectCourse('Automation Testing Masterclass');
    const overall = await grades.getOverallGrade();
    expect(overall).toMatch(/[A-F][+-]?/);
    const assignments = await grades.getAssignmentScores();
    expect(assignments.length).toBeGreaterThan(0);
    if (overall.startsWith('A') || overall.startsWith('B')) {
      const cert = new CertificatePage(page);
      await cert.navigate();
      await expect(cert.certificateAvailable('Automation Testing Masterclass')).toBeVisible();
      await cert.downloadCertificate('Automation Testing Masterclass');
      const download = await page.waitForEvent('download');
      expect(download.suggestedFilename()).toContain('certificate');
    }
  });
});
